for match in re.finditer(r'patient\s+(\d+).*?(?:severely elevated|significantly elevated|elevated|high|abnormal|borderline-high).*?([\d.]+)\s*mg/dL|([\d.]+)\s*mg/dL.*?(?:severely elevated|significantly elevated|elevated|high|abnormal|borderline-high)', lab_content, re.IGNORECASE):
